INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Traffic Alarm', 'Traffic Alarm is a mobile traffic management game where players control traffic lights to guide vehicles safely and efficiently through busy intersections. The goal is to prevent accidents while maximizing traffic flow within a limited time. Featuring multiple levels with increasing difficulty, unique badge challenges, and colorful 2D graphics, Traffic Alarm offers a fun yet strategic experience for players of all ages. Currently available on Android.' FROM games WHERE igdb_id = 360994 ON CONFLICT (game_id, language_code) DO NOTHING;
