INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('a-lakeside-walk-in-the-dolomites', 341085, '2025-04-07', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9pbw.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3j4f.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A Lakeside Walk in the Dolomites', 'A solitary evening walk along one of the most beautiful lakes in the Dolomites. The air in Alleghe is crisp, the stillness envelops the path, and the water glistens with the last rays of the sun. Suddenly, the silence shifts. It grows dense. A noise stirs in the woods, a shadow slipping beyond your gaze. Is solitude your only company? With every step, you venture further; at every corner, another piece of a lost mystery unfolds. As you move deeper into the unnatural quiet of the forest, doubts creep in. Are these really just old stories? And the lake... the lake watches.' FROM games WHERE igdb_id = 341085 ON CONFLICT (game_id, language_code) DO NOTHING;
