INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vivat Slovakia', 'Vivat Slovakia is a third-person shooter set in the 90s´ Bratislava, the capital of Slovakia, where the streets are full of thugs and local mafia supported by the corrupted government. The game contains five weapons to use, 30 classic cars of that time to drive and one open city to explore.' FROM games WHERE igdb_id = 216496 ON CONFLICT (game_id, language_code) DO NOTHING;
