INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jiǔzhōu Jiàn Gē', 'Jiuzhou Jian Ge is a 3D Wuxia MMORPG, crafted with cutting-edge next-generation technology to bring the most authentic fantasy martial arts world to life. Experience a vast Jianghu of vendettas and brotherhood, explore meticulously designed immersive maps, master elegant and powerful Qinggong, and face countless rare beasts. Engage in thrilling duels at Huashan, fight for supremacy on Songshan, and forge a one-of-a-kind martial world that belongs only to you!' FROM games WHERE igdb_id = 367405 ON CONFLICT (game_id, language_code) DO NOTHING;
