INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Recyclamation', 'Recyclamation is a gritty sci-fi job simulator. The victim of a mind-wiping process, you sort trash as you regain your lost memories and uncover the truth of who you are and the world around you. Will you learn who you were and how you came here, or will you continue your life as a mindless drone?' FROM games WHERE igdb_id = 380201 ON CONFLICT (game_id, language_code) DO NOTHING;
