INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ZombMe', 'ZombMe is a 2D platformer based on old-school platformers with influences and callbacks to Mario, Sonic, Bonk, Bionic Commando, MetalStorm, and Mega Man. The hook with ZombMe, though, is that you''re a zombie who is trying to stay DEAD--so the traditional gameplay mechanics of needing health is reversed: catching fire and jumping on spikes is good, and getting health packs is bad!' FROM games WHERE igdb_id = 343795 ON CONFLICT (game_id, language_code) DO NOTHING;
