INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pixicharm: Celestibun', 'Celestibun takes you on a whimsical run through an enchanted forest, where a brave little bunny girl dashes beneath glowing canopies to gather shimmering stars. Quick reflexes are key as buzzing wasps swoop and slow snails block the path, but every leap and hop carries you farther into the magical woods. Simple to play and endlessly replayable, it’s a charming adventure for anyone who loves fast, lighthearted fun.' FROM games WHERE igdb_id = 378768 ON CONFLICT (game_id, language_code) DO NOTHING;
