INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pinono and the Magic Fiddle', 'Pinono, a girl who casts magic through music, sets off on a slightly free-spirited journey. In this turn-based RPG, you''ll meet unique companions and explore a whimsical world. Your choices shape the story and ending, and melodies used in magic and events are procedurally generated each time.' FROM games WHERE igdb_id = 355101 ON CONFLICT (game_id, language_code) DO NOTHING;
