INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('silent-watcher', 363080, '2025-08-14', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coacfv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar42or.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Silent Watcher', 'You''re waiting for your partner at home. But something isn''t right. You feel a presence, something watching you... from every window, every shadow. In Silent Watcher, fear isn''t what you see—it''s what you feel. A psychological horror where the enemy is always there.' FROM games WHERE igdb_id = 363080 ON CONFLICT (game_id, language_code) DO NOTHING;
