INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'QuackSquad', 'Join our fearless feathered hero on an epic adventure to defend their pond from an invasion of zombie chickens spawned by sinister fast-food joints lurking nearby. In this thrilling top-down shooter, arm yourself to the beak with an arsenal of weapons as you face off against relentless waves of undead poultry and formidable bosses. But fear not, for you are not alone! Level up your duck, recruit loyal companions, and engage in exciting minigames to bolster your forces.' FROM games WHERE igdb_id = 350812 ON CONFLICT (game_id, language_code) DO NOTHING;
