INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jikoronpa: Laments of Isolation', 'Jikoronpa: Laments of Isolation is a fangame for the series Danganronpa from Spike Chunsoft. It has no official relations to it and is completely non-profit. This game may contain sensitive topics or implied mentions of topics such as abuse or suicide. There will also be depictions of gore as well. If you may feel uncomfortable with these things, please exercise caution before playing. (Up to Chapter 3 Trial)' FROM games WHERE igdb_id = 341073 ON CONFLICT (game_id, language_code) DO NOTHING;
