INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crime Simulator', 'You’re out of jail, but the debt isn’t gone. Sneak, steal, and break into houses solo or in 4-player co-op. Use lockpicks, sleeping gas, and brute force to complete jobs, outsmart security, and make enough money before time runs out. Will you pay back what you owe, or lose everything?' FROM games WHERE igdb_id = 301426 ON CONFLICT (game_id, language_code) DO NOTHING;
