INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tireless: Prepare For the Adrenaline', 'Tireless is a Challenging Sci-fi 3D Platformer that takes speed to cosmic levels. As a ''Pacer'' robot in space, master movement and evade obstacles at extreme speeds. Easy to pick up but challenging to dominate, this skill-based game offers a thrilling experience, relying solely on your expertise to conquer each meticulously designed level. Enjoy seamless gameplay with responsive controls and complete freedom of movement, offering a truly off-the-rails experience.' FROM games WHERE igdb_id = 103279 ON CONFLICT (game_id, language_code) DO NOTHING;
