INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stack Attack', 'Stack Attack is a trip down nostalgia avenue. Taking the form of a fully Twitch integrated (Required) app, your chat attempts to gain the most caps by taking turns knocking down the stack and seeing which caps they can flip over. Increases chat engagement and, thus, algorithm response!' FROM games WHERE igdb_id = 363635 ON CONFLICT (game_id, language_code) DO NOTHING;
