INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Eternity', 'You play as a man shattered by tragedy, desperate to move on. When a mysterious corporation called Exracon offers him a job, it feels like a second chance. But behind its walls lies a brutal psychological nightmare — where memories twist, reality fractures, and survival means questioning what’s real, and what Exracon truly wants. Escape your past… or be consumed by it.' FROM games WHERE igdb_id = 387968 ON CONFLICT (game_id, language_code) DO NOTHING;
