INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Realization', 'A self-staged arson at a sales center drags you into the murder case of a female sales agent. With both your career and life in shambles, you must find a way to clear your name. The path to the truth is fraught with danger. Can you rise from this abyss and reclaim the reality you once envisioned?' FROM games WHERE igdb_id = 345438 ON CONFLICT (game_id, language_code) DO NOTHING;
