INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ultimate Grandma Simulator', 'Who said Grandma needs help crossing the road? Take care of a fragile, old Grandma as she sets forth on a grand adventure, stepping outside the comfort of her home to explore the world in search of her grandchild, Tommy. Maneuver across treacherous bridges and obstacles, where even the slightest nudge will send you toppling over. Complete 10 platforming-based levels set in a wide variety of map locations, including a busy cityscape, a rowdy elementary school, and more.' FROM games WHERE igdb_id = 368252 ON CONFLICT (game_id, language_code) DO NOTHING;
