INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Winter Clothing', 'This is a horror plot puzzle game with Chinese folk themes. There is an unwritten rule in Tianhe Town: on the day of the Winter Clothing Festival, no villager is allowed to approach the back mountain. Is there really a ghost on the mountain? Perhaps there is something more terrifying than ghosts.' FROM games WHERE igdb_id = 333968 ON CONFLICT (game_id, language_code) DO NOTHING;
