INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'My Life with You', 'My Life with You is a gentle, text-light narrative experience in which you follow the daily journey of a young single mother navigating life’s challenges—caring for her child, searching for work, and managing household responsibilities while living with her grandmother. The game focuses on the emotional bond between mother and child, balancing struggles and growth at a self-paced rhythm, free from timers or pressure.' FROM games WHERE igdb_id = 348969 ON CONFLICT (game_id, language_code) DO NOTHING;
