INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Contrabandist: Contraband Cartel Simulator', 'Step into the dangerous and thrilling role of cartel in the ruthless world of Contrabandist: Contraband Cartel Simulator! In this high-stakes crime simulation, you begin as a small-time hustler and rise to become one of the most feared barons in the drug trade. Navigate the treacherous underworld, where wealth, power, and violence go hand in hand. Outwit rival cartels, bribe officials, and smuggle contraband across dangerous borders as you build a criminal empire that spans continents.' FROM games WHERE igdb_id = 370613 ON CONFLICT (game_id, language_code) DO NOTHING;
