INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bearly Brave', 'Bearly Brave is a 2D roguelike deck-building game set in a deceptively charming toy shop, where the cutest teddy bears come to life each night to fight in a no-holds-barred tournament that determines their placement on the shelves, and thus their likeness to be taken to their forever home.' FROM games WHERE igdb_id = 355406 ON CONFLICT (game_id, language_code) DO NOTHING;
