INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wall of Insanity 2', 'Wall of Insanity 2 once again plunges us into a grim and perilous world, lurking beyond the veil of dimensions — a world of isolation and decay. It is a nightmare from which there is no waking. In this third-person action game, you will uncover the story of a lost squad while confronting an unspeakable horror' FROM games WHERE igdb_id = 365847 ON CONFLICT (game_id, language_code) DO NOTHING;
