INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Amazeballs!', 'Amazeballs! is a calm, top-down 2D maze pathfinding game for people who enjoy relaxing with patterns and movement. Relax and enjoy the soothing mental exercise of finding the patterns in the maze, competing only against yourself.' FROM games WHERE igdb_id = 360668 ON CONFLICT (game_id, language_code) DO NOTHING;
