INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('personal-best', 369440, '2025-08-03', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coaj92.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sczaxo.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Personal Best', 'Personal Best is a Momentum Platformer. The player must navigate through the various paths that make up each level on their way to the Stopwatch at the end. However, they have a limited amount of time to progress, and when that timer runs out, their score (gained via collecting Charms throughout the level, as well as just making their way to the end) are tallied up and converted into EXP and Points. They''re then sent to the Upgrade Menu where those points can be used to purchase upgrades, allowing the player to better navigate and further progress in the level.' FROM games WHERE igdb_id = 369440 ON CONFLICT (game_id, language_code) DO NOTHING;
