INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Short Snow', 'SHORT SNOW! Realistic open-world survival experience, you find yourself lost in a vast, snow-covered forest after a harrowing plane crash. With temperatures plummeting and hunger gnawing at you, will you succumb to the forces of nature, or will you conquer the frozen wilderness? The choice is yours!' FROM games WHERE igdb_id = 309867 ON CONFLICT (game_id, language_code) DO NOTHING;
