INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jaro TCG', 'Jaro TCG is a digital trading card game simulator where players can build decks, and engage in strategic battles using a fully customizable card system. Set in a rich original universe, Jaro TCG offers immersive mechanics, full card collection, and multiplayer duels designed to recreate the feel of a physical card game—digitally. Whether you''re testing new strategies, or playing with friends, Jaro TCG is the perfect sandbox for card game enthusiasts.' FROM games WHERE igdb_id = 339874 ON CONFLICT (game_id, language_code) DO NOTHING;
