INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blackout Football Manager', 'Blackout Football Manager is a football-club management sim where you build a squad, devise training plans and tactics, upgrade facilities, handle high-level finances, and join local and international federations (guilds). A card-based management system lets you boost players on the field, heal injuries, and train harder, while players’ distinct mental and physical attributes shape match strategy. Scout opponents, trade on an in-game market, and unlock tech trees to expand infrastructure, refine training regimes, and customize formations on the path to league success.' FROM games WHERE igdb_id = 359841 ON CONFLICT (game_id, language_code) DO NOTHING;
