INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Time Space Rebuild', 'In "Time Rebuild", human civilization stands on the brink of destruction. You will become a time-traveling hero, embarking on a journey to save the world while encountering and bonding with women of vastly different appearances and personalities.' FROM games WHERE igdb_id = 344228 ON CONFLICT (game_id, language_code) DO NOTHING;